class Recall(nn.Module):
    def __init__(s, b, d=32, vocab=128, **kw):
        super().__init__()
        s.emb, s.head = nn.Embedding(vocab, d), nn.Linear(d, vocab)
        s.shift = nn.Linear(2 * d, d)                  # token shift: x_t with x_{t-1}
        s.ttt = nn.ModuleList(TTTLinear(d, b, **kw) for _ in range(2))
        s.norm = nn.ModuleList(nn.LayerNorm(d) for _ in range(2))
    def forward(s, idx):
        x = s.emb(idx)
        x = s.shift(torch.cat([x, F.pad(x, (0, 0, 1, 0))[:, :-1]], -1))
        for n, layer in zip(s.norm, s.ttt):
            x = x + layer(n(x))
        return s.head(x)

def train(b, steps=1500, seed=0, **kw):
    torch.manual_seed(seed)
    model = Recall(b, **kw)
    opt = torch.optim.AdamW(model.parameters(), lr=3e-3)
    for step in range(steps):
        seq, tgt = recall_batch(64)
        loss = F.cross_entropy(model(seq).flatten(0, 1), tgt.flatten(), ignore_index=-100)
        opt.zero_grad(); loss.backward(); opt.step()  # backprop runs through every inner step
    seq, tgt = recall_batch(2048)
    with torch.no_grad():
        pred = model(seq).argmax(-1)
    m = tgt != -100
    return (pred[m] == tgt[m]).float().mean().item()
